738			t.Fatal("ledger grew on idempotent pending apply")
739		}
740		// 内容不同：冲突。
741		conflict := in
742		conflict.EstimatedFee = 21
743		if _, err := w.Apply(conflict); !errors.Is(err, ErrConflict) {
744			t.Fatalf("err = %v, want ErrConflict", err)
745		}
746		// 批准后重复申请：返回已预留结果，不重复预留。
747		if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); err != nil {
748			t.Fatal(err)
749		}
750		if req, err := w.Apply(in); err != nil || req.State != RequestReserved {
751			t.Fatalf("re-apply after approve: view=%+v err=%v", req, err)
752		}
753		bal, _ := w.Balance("payer")
754		if bal != (Balances{Available: 80, Reserved: 20}) {
755			t.Fatalf("balance = %+v, want {80 20} (no double reserve)", bal)
756		}
757	}
