374			{"account mismatch", func(in *RequestInput) {
375				in.AccountID = "u2"
376				in.SessionID = "s1"
377			}, ErrSessionAccountMismatch},
378			{"device mismatch", func(in *RequestInput) { in.DeviceID = "wrong" }, ErrSessionDeviceMismatch},
379		}
380		for _, tc := range cases {
381			t.Run(tc.name, func(t *testing.T) {
382				in := baseApply()
383				tc.mutate(&in)
384				if _, err := w.Apply(in); !errors.Is(err, tc.wantErr) {
385					t.Fatalf("err = %v, want %v", err, tc.wantErr)
386				}
387			})
388		}
389	
390		// 到期边界：到期时刻及之后拒绝。
391		in := baseApply()
392		in.RequestID = "r-expiry"
393		c.t = c.t.Add(time.Minute)
394		if _, err := w.Apply(in); !errors.Is(err, ErrSessionExpired) {
395			t.Fatalf("at expiry err = %v", err)
396		}
397		c.t = c.t.Add(-time.Minute).Add(time.Second) // 到期前 59 秒仍有效，但换个请求号
398		in.RequestID = "r-valid"
399		if _, err := w.Apply(in); err != nil {
400			t.Fatalf("just before expiry should pass session check: %v", err)
401		}
402	
403		// 吊销：新申请拒绝；已预留请求仍可结算。
404		if err := w.RevokeSession("s2"); err != nil {
405			t.Fatal(err)
406		}
407		in2 := baseApply()
408		in2.AccountID, in2.SessionID, in2.DeviceID, in2.RequestID = "u2", "s2", "dev2", "r2"
409		if _, err := w.Apply(in2); !errors.Is(err, ErrSessionRevoked) {
410			t.Fatalf("revoked session err = %v", err)
411		}
412		if _, err := w.Settle("u1", "r-valid", 10); err != nil {
413			t.Fatalf("settle after another session revoked: %v", err)
414		}
415	}
