420		// 窗口边界：含开始、不含结束（窗口完全落在会话有效期内）。
421		p := validPolicy(c)
422		p.ID = "p-window"
423		p.StartsAt = c.t.Add(30 * time.Second)
424		p.EndsAt = c.t.Add(50 * time.Second)
