443		// 默认策略 p1 的各类不匹配。
444		c.t = c.t.Add(-time.Minute)
445		for _, tc := range []struct {
446			name   string
447			mutate func(*RequestInput)
448		}{
449			{"unallowed account", func(in *RequestInput) {
450				mustAccount(t, w, "u3", 0)
451				in.AccountID, in.SessionID, in.DeviceID = "u3", "s3", "dev3"
452				if _, err := w.CreateSession("s3", "u3", "dev3", c.t.Add(time.Minute)); err != nil {
453					t.Fatal(err)
454				}
455			}},
456			{"wrong operation", func(in *RequestInput) { in.Operation = "x" }},
457			{"wrong payee", func(in *RequestInput) { in.Payee = "x" }},
458			{"unknown policy", func(in *RequestInput) { in.PolicyID = "nope" }},
459		} {
