461				in := baseApply()
462				in.RequestID = "deny-" + tc.name
463				tc.mutate(&in)
464				_, err := w.Apply(in)
465				if err == nil {
466					t.Fatal("expected denial")
467				}
468				if !errors.Is(err, ErrPolicyDenied) && !errors.Is(err, ErrPolicyNotFound) {
469					t.Fatalf("err = %v", err)
